contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address log, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);
        c.SetLogFile(log); if (__ESBMC_reverted()) return;
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;

        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint minAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(reverted == false || minAfter == minBefore);
    }

    receive() external payable {}
}

