// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(address log, uint256 minSum) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        try c.SetLogFile(log) {} catch { return; }
        try c.SetMinSum(minSum) {} catch { return; }
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        bool reverted;
        try c.Initialized() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 minAfter;
        try c.MinSum() returns (uint256 __r) { minAfter = __r; } catch { return; }
        assertTrue(reverted == false || minAfter == minBefore);
    }

    function testFuzz_run(address log, uint256 minSum) public {
        vm.assume(log.code.length == 0 && uint160(log) > 0xffff && log != address(this) && log != address(c) && log != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && log != 0x000000000000000000636F6e736F6c652e6c6f67 && log != 0x4e59b44847b379578588920cA78FbF26c0B4956C && log != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(log, minSum);
    }

    receive() external payable {}
}
